1	interface Item {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	}
6	
7	interface QuoteStep {
8	  op: "quote";
9	  items: Item[];
10	}
11	
12	interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	interface ClaimStep {
18	  op: "claim";
19	  policy: number;
20	  incident: { cause: string; damages: Damage[] };
21	}
22	
23	type Step = QuoteStep | ClaimStep;
24	
25	interface Scenario {
26	  customer: { yearsWithMHPCO: number };
27	  steps: Step[];
28	}
29	
30	interface QuoteResult {
31	  premium: number;
32	}
33	
34	interface ClaimResult {
35	  payout: number;
36	  remainingCap: number;
37	}
38	
39	type StepResult = QuoteResult | ClaimResult;
40	
41	const BASE_PREMIUM: Record<string, number> = {
42	  sword: 100,
43	  amulet: 60,
44	  staff: 80,
45	  potion: 40,
46	  rune: 25,
47	};
48	
49	const PROCESSING_FEE = 5;
50	const FIRST_INSURANCE_SURCHARGE = 0.1;
51	
52	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
53	const COMPONENT_UNIT_PREMIUM = 25;
54	const COMPONENT_BLOCK_SIZE = 3;
55	const COMPONENT_BLOCK_PREMIUM = 60;
56	
57	const componentGroupBase = (count: number): number =>
58	  count === COMPONENT_BLOCK_SIZE
59	    ? COMPONENT_BLOCK_PREMIUM
60	    : count * COMPONENT_UNIT_PREMIUM;
61	
62	const componentsBase = (components: Item[]): number => {
63	  const countsByType = new Map<string, number>();
64	  for (const component of components) {
65	    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
66	  }
67	  return [...countsByType.values()].reduce(
68	    (total, count) => total + componentGroupBase(count),
69	    0,
70	  );
71	};
72	
73	const isComponent = (item: Item): boolean =>
74	  COMPONENT_TYPES.has(item.type);
75	
76	const itemsBase = (items: Item[]): number => {
77	  const mainBase = items
78	    .filter((item) => !isComponent(item))
79	    .reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
80	  return mainBase + componentsBase(items.filter(isComponent));
81	};
82	
83	const CURSE_SURCHARGE = 0.5;
84	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
85	const HIGH_ENCHANTMENT_THRESHOLD = 5;
86	
87	// Sum `rate * base premium` for every item matching `applies`. The additive
88	// per-item form keeps each surcharge a flat term so quotePremium stays additive
89	// (see the float-drift note there).
90	const itemSurcharge = (
91	  items: Item[],
92	  applies: (item: Item) => boolean,
93	  rate: number,
94	): number =>
95	  items.reduce(
96	    (sum, item) => sum + (applies(item) ? BASE_PREMIUM[item.type] * rate : 0),
97	    0,
98	  );
99	
100	const curseSurcharge = (items: Item[]): number =>
101	  itemSurcharge(items, (item) => item.cursed === true, CURSE_SURCHARGE);
102	
103	const highEnchantmentSurcharge = (items: Item[]): number =>
104	  itemSurcharge(
105	    items,
106	    (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
107	    HIGH_ENCHANTMENT_SURCHARGE,
108	  );
109	
110	const LOYALTY_DISCOUNT = 0.2;
111	const LOYALTY_THRESHOLD_YEARS = 2;
112	const FOLLOWUP_DISCOUNT = 0.15;
113	
114	const loyaltyDiscount = (base: number, yearsWithMHPCO: number): number =>
115	  yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? base * LOYALTY_DISCOUNT : 0;
116	
117	const followupDiscount = (base: number, isFollowup: boolean): number =>
118	  isFollowup ? base * FOLLOWUP_DISCOUNT : 0;
119	
120	// Always-on surcharge charged on every policy, expressed as a flat term so
121	// quotePremium stays additive (see the float-drift note there).
122	const firstInsuranceSurcharge = (base: number): number =>
123	  base * FIRST_INSURANCE_SURCHARGE;
124	
125	const quotePremium = (
126	  items: Item[],
127	  yearsWithMHPCO: number,
128	  isFollowup: boolean,
129	): number => {
130	  const base = itemsBase(items);
131	  const surcharges =
132	    firstInsuranceSurcharge(base) +
133	    curseSurcharge(items) +
134	    highEnchantmentSurcharge(items);
135	  const discounts =
136	    loyaltyDiscount(base, yearsWithMHPCO) + followupDiscount(base, isFollowup);
137	  // Sum flat terms rather than scaling `base * (1 + rate)`: the additive form
138	  // avoids IEEE-754 drift that would otherwise round wrong under Math.ceil.
139	  return Math.ceil(base + surcharges - discounts + PROCESSING_FEE);
140	};
141	
142	const DEDUCTIBLE = 100;
143	const CAP_MULTIPLIER = 2;
144	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
145	const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
146	
147	const INSURANCE_VALUE: Record<string, number> = {
148	  sword: 1000,
149	  amulet: 600,
150	  staff: 800,
151	  potion: 400,
152	  rune: 250,
153	  moonstone: 250,
154	};
155	
156	const insuranceSum = (items: Item[]): number =>
157	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
158	
159	// Reimbursement for a single damage before the deductible. Items enchanted to
160	// level 8+ are reimbursed at only 50% of the damage amount.
161	const reimbursement = (item: Item, amount: number): number =>
162	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
163	    ? amount * HIGH_ENCHANTMENT_REIMBURSEMENT
164	    : amount;
165	
166	// Each damaged item is reimbursed (subject to clauses) less one deductible,
167	// floored in MHPCO's favor.
168	const damagesPayout = (damages: Damage[], policyItems: Item[]): number =>
169	  Math.floor(
170	    damages.reduce((sum, damage) => {
171	      const item = policyItems.find((i) => i.type === damage.itemType) as Item;
172	      return sum + (reimbursement(item, damage.amount) - DEDUCTIBLE);
173	    }, 0),
174	  );
175	
176	const claimResult = (claim: ClaimStep, policyItems: Item[]): ClaimResult => {
177	  const cap = CAP_MULTIPLIER * insuranceSum(policyItems);
178	  const payout = damagesPayout(claim.incident.damages, policyItems);
179	  return { payout, remainingCap: cap - payout };
180	};
181	
182	export const runScenario = (scenario: Scenario): { results: StepResult[] } => {
183	  const results = scenario.steps.map((step, index): StepResult => {
184	    if (step.op === "claim") {
185	      const policy = scenario.steps[step.policy] as QuoteStep;
186	      return claimResult(step, policy.items);
187	    }
188	    // Every quote after the first is a follow-up contract; the map index is
189	    // already the count of quotes seen so far, so no separate counter is needed.
190	    const isFollowup = index > 0;
191	    return {
192	      premium: quotePremium(step.items, scenario.customer.yearsWithMHPCO, isFollowup),
193	    };
194	  });
195	  return { results };
196	};
